-- Generated by wow-addon-porter (profile: forever) for NameplateSCT.
-- Only NameplateSCT_Camelot.toc loads this file, so other clients never see it.
-- It holds replacements for APIs that WoW Forever removed or changed. They are kept in one
-- table, ForeverPort_NameplateSCT, and never written to the old global names: other addons test those
-- globals to choose a client path. Each patched file reads them through
-- (ForeverPort_NameplateSCT or _G), which falls back to the original globals on other clients.
local C = {}
local issecretvalue, issecrettable = issecretvalue, issecrettable
local function Secret(value) return issecretvalue ~= nil and issecretvalue(value) end
local function SecretTable(value) return issecrettable ~= nil and issecrettable(value) end
C.IsForever = true
C.IsSecret = Secret
-- Spell book type of the old API ("spell"/BOOKTYPE_SPELL, "pet"/BOOKTYPE_PET) as Enum.SpellBookSpellBank.
local function SpellBank(bookType)
	if bookType == "pet" or (Enum.SpellBookSpellBank and bookType == Enum.SpellBookSpellBank.Pet) then
		return Enum.SpellBookSpellBank.Pet
	end
	return Enum.SpellBookSpellBank.Player
end

-- Forever returns a table. Old returns: name, rank, icon, castTime, minRange, maxRange,
-- spellID, originalIcon. The rank comes from the spell's subtext.
do
	local GetSpellInfo, GetSpellSubtext = C_Spell.GetSpellInfo, C_Spell.GetSpellSubtext
	function C.GetSpellInfo(spell)
		if spell == nil then return end
		local info = GetSpellInfo(spell)
		if not info then return end
		local rank = info.spellID and GetSpellSubtext and GetSpellSubtext(info.spellID) or nil
		return info.name, rank, info.iconID, info.castTime, info.minRange, info.maxRange, info.spellID, info.originalIconID
	end
end

-- Still exists, but on Forever the two units must be comparable (C_Secrets.CanCompareUnitTokens) and the result can
-- be secret; testing a secret throws. Returns nil then (callers treat the units as different), as ElvUI's oUF does.
do
	local UnitIsUnit, issecretvalue = UnitIsUnit, issecretvalue
	local CanCompare = C_Secrets and C_Secrets.CanCompareUnitTokens
	function C.UnitIsUnit(unit1, unit2)
		if unit1 == nil or unit2 == nil then return UnitIsUnit(unit1, unit2) end
		if CanCompare and not CanCompare(unit1, unit2) then return nil end
		local isUnit = UnitIsUnit(unit1, unit2)
		if issecretvalue and issecretvalue(isUnit) then return nil end
		return isUnit
	end
end

-- CVars that Forever renamed (the floating combat text ones gained a _v2 suffix).
-- SetCVar fails on a name the client doesn't know.
do
	local CVARS = {
		["floatingCombatTextAuras"] = "floatingCombatTextAuras_v2",
		["floatingCombatTextCombatDamage"] = "floatingCombatTextCombatDamage_v2",
		["floatingCombatTextCombatHealing"] = "floatingCombatTextCombatHealing_v2",
		["floatingCombatTextCombatHealingAbsorbSelf"] = "floatingCombatTextCombatHealingAbsorbSelf_v2",
		["floatingCombatTextCombatHealingAbsorbTarget"] = "floatingCombatTextCombatHealingAbsorbTarget_v2",
		["floatingCombatTextCombatLogPeriodicSpells"] = "floatingCombatTextCombatLogPeriodicSpells_v2",
		["floatingCombatTextCombatState"] = "floatingCombatTextCombatState_v2",
		["floatingCombatTextComboPoints"] = "floatingCombatTextComboPoints_v2",
		["floatingCombatTextDamageReduction"] = "floatingCombatTextDamageReduction_v2",
		["floatingCombatTextDodgeParryMiss"] = "floatingCombatTextDodgeParryMiss_v2",
		["floatingCombatTextEnergyGains"] = "floatingCombatTextEnergyGains_v2",
		["floatingCombatTextFloatMode"] = "floatingCombatTextFloatMode_v2",
		["floatingCombatTextFriendlyHealers"] = "floatingCombatTextFriendlyHealers_v2",
		["floatingCombatTextHonorGains"] = "floatingCombatTextHonorGains_v2",
		["floatingCombatTextLowManaHealth"] = "floatingCombatTextLowManaHealth_v2",
		["floatingCombatTextPeriodicEnergyGains"] = "floatingCombatTextPeriodicEnergyGains_v2",
		["floatingCombatTextReactives"] = "floatingCombatTextReactives_v2",
		["floatingCombatTextRepChanges"] = "floatingCombatTextRepChanges_v2",
		["floatingCombatTextSpellMechanics"] = "floatingCombatTextSpellMechanics_v2",
		["floatingCombatTextSpellMechanicsOther"] = "floatingCombatTextSpellMechanicsOther_v2",
	}
	local SetCVar, GetCVar, GetCVarBool, GetCVarDefault = SetCVar, GetCVar, GetCVarBool, GetCVarDefault
	function C.SetCVar(name, ...) return SetCVar(CVARS[name] or name, ...) end
	function C.GetCVar(name, ...) return GetCVar(CVARS[name] or name, ...) end
	function C.GetCVarBool(name, ...) return GetCVarBool(CVARS[name] or name, ...) end
	function C.GetCVarDefault(name, ...) return GetCVarDefault(CVARS[name] or name, ...) end
end

-- Event registration that reaches the client: a frame using the client's own method, or an
-- object whose method is AceEvent-3.0's (it registers on a frame). The combat log events can't
-- be registered on addon frames on Forever, so they are not registered; renamed events
-- register under their new name; a name the client doesn't know (a Blizzard event Forever
-- removed) goes through pcall, because registering it throws. Any other object has its own
-- event system (Details listeners, a priority helper's synthesized combat log): its call is
-- passed on unchanged. Everything not registered is listed in ForeverPort_NameplateSCT.SkippedEvents.
do
	local SKIP = {
		["COMBAT_LOG_EVENT"] = true,
		["COMBAT_LOG_EVENT_UNFILTERED"] = true,
	}
	local RENAMED = {
		["LEARNED_SPELL_IN_TAB"] = "LEARNED_SPELL_IN_SKILL_LINE",
	}
	local IsEventValid = C_EventUtils and C_EventUtils.IsEventValid
	local rawget, type = rawget, type
	local skipped = {}
	C.SkippedEvents = skipped
	-- "frame", "ace" or nil (the object's own event system)
	local function ReachesClient(obj, method)
		if type(obj) ~= "table" then return nil end
		local own = rawget(obj, method)
		if own == nil then return type(rawget(obj, 0)) == "userdata" and "frame" or nil end
		local AceEvent = LibStub and LibStub("AceEvent-3.0", true)
		if AceEvent ~= nil and own == AceEvent[method] then return "ace" end
	end
	local function Call(frame, method, event, ...)
		local kind = type(event) == "string" and ReachesClient(frame, method)
		if not kind then return frame[method](frame, event, ...) end
		local new = RENAMED[event]
		if new then
			-- AceEvent calls the method named after the event when no handler is given: keep the old name.
			if kind == "ace" and method == "RegisterEvent" and select("#", ...) == 0 then
				return frame[method](frame, new, event)
			end
			event = new
		end
		if SKIP[event] then
			skipped[event] = "can't be registered on addon frames on Forever"
			return
		end
		if IsEventValid and not IsEventValid(event) then
			local ok, result = pcall(frame[method], frame, event, ...)
			if not ok then skipped[event] = result end
			return result
		end
		return frame[method](frame, event, ...)
	end
	C["Frame:RegisterEvent"] = function(frame, event, ...) return Call(frame, "RegisterEvent", event, ...) end
	C["Frame:RegisterUnitEvent"] = function(frame, event, ...) return Call(frame, "RegisterUnitEvent", event, ...) end
	C["Frame:UnregisterEvent"] = function(frame, event, ...) return Call(frame, "UnregisterEvent", event, ...) end
end

ForeverPort_NameplateSCT = C
